# LessonSkill is a catalog/coverage link, not prerequisite evidence. Keep the
# primary authored skill as the only seeded link so secondary mappings cannot
# turn one lesson completion into evidence for an uncompleted skill.
LESSON_SKILLS = [(lesson["id"], lesson["skill_id"]) for lesson in LESSONS]

# `conditions-v1` was published in the first course wave, before lesson
# prerequisites were validated against the graph. Its authored content is
# immutable by project decision, so the mismatch is recorded here instead of
# being rewritten in place.
LEGACY_PREREQUISITE_EXEMPT = frozenset({"conditions-v1"})

def validate_graph():
 ids={item["id"] for item in SKILLS}
 if len(ids)!=len(SKILLS): raise ValueError("Duplicate skill id")
 if not 80 <= len(SKILLS) <= 150: raise ValueError("Python Backend graph must contain 80-150 skills")
 for source,target,relation in EDGES:
  if source not in ids or target not in ids: raise ValueError("Skill edge references missing skill")
  if relation not in {"prerequisite", "related", "specialization"}: raise ValueError("Invalid skill edge relation")
 if any(source==target and relation == "prerequisite" for source,target,relation in EDGES): raise ValueError("Self-cycle in prerequisite graph")
 adjacency={skill:[] for skill in ids}
 for source,target,relation in EDGES:
  if relation == "prerequisite": adjacency[source].append(target)
 visiting=set(); visited=set()
 def visit(node):
  if node in visiting: raise ValueError("Cycle in skill graph")
  if node in visited:return
  visiting.add(node)
  for child in adjacency[node]: visit(child)
  visiting.remove(node);visited.add(node)
 for node in ids: visit(node)
 lesson_ids={lesson["id"] for lesson in LESSONS}
 if any(lesson not in lesson_ids or skill not in ids for lesson,skill in LESSON_SKILLS): raise ValueError("Invalid lesson-skill link")
 if {lesson for lesson,_ in LESSON_SKILLS} != lesson_ids: raise ValueError("Every lesson must be linked to a skill")
 _legacy_declared=set(LEGACY_PREREQUISITE_EXEMPT)
 _graph_pred={target:set() for target in ids}
 for source,target,relation in EDGES:
  if relation=="prerequisite": _graph_pred[target].add(source)
 for lesson in LESSONS:
  if lesson["id"] in _legacy_declared: continue
  declared=set(lesson.get("prerequisites") or ())
  if declared!=_graph_pred.get(lesson["skill_id"],set()): raise ValueError(f"Lesson {lesson['id']} prerequisites must match graph edges")
 if any(not 0 <= item["difficulty"] <= 1 or not 0 <= item["importance"] <= 1 for item in SKILLS):
  raise ValueError("Skill difficulty and importance must be between 0 and 1")
validate_graph()

def seed_skill_graph(db):
 validate_graph()
 for item in SKILLS:
  skill=db.get(Skill,item["id"]) or Skill(id=item["id"],name=item["name"],category=item["category"],difficulty=item["difficulty"],importance=item["importance"],tags=item["tags"],description=item["description"])
  skill.name=item["name"];skill.category=item["category"];skill.difficulty=item["difficulty"];skill.importance=item["importance"];skill.tags=item["tags"];skill.description=item["description"];db.add(skill)
 db.flush()
 for source,target,relation in dict.fromkeys(tuple(edge) for edge in EDGES):
  if db.query(SkillEdge).filter_by(from_skill_id=source,to_skill_id=target,relation=relation).first() is None: db.add(SkillEdge(from_skill_id=source,to_skill_id=target,relation=relation))
  db.flush()
 for lesson_id,skill_id in LESSON_SKILLS:
  if db.query(LessonSkill).filter_by(lesson_id=lesson_id,skill_id=skill_id).first() is None: db.add(LessonSkill(lesson_id=lesson_id,skill_id=skill_id))
 db.flush()


def skill_graph(db):
    """Return the authored graph in a stable, API-friendly shape."""
    seed_skill_graph(db)
    skills = db.scalars(select(Skill).order_by(Skill.category, Skill.difficulty, Skill.id)).all()
    edges = db.scalars(select(SkillEdge).order_by(SkillEdge.from_skill_id, SkillEdge.to_skill_id)).all()
    links = db.scalars(select(LessonSkill).order_by(LessonSkill.lesson_id, LessonSkill.skill_id)).all()
    return skills, edges, links
